select 'fadm_session_lookup is SECURITY DEFINER' as rule, exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'desk' and p.proname = 'fadm_session_lookup' and p.prosecdef) as ok
union all select 'only desk_app can execute it', has_function_privilege('desk_app', 'desk.fadm_session_lookup(bytea)', 'execute') and not has_function_privilege('public', 'desk.fadm_session_lookup(bytea)', 'execute')
union all select 'session create and revoke are desk_app only', has_function_privilege('desk_app', 'desk.fadm_session_create(uuid,bytea,integer)', 'execute') and has_function_privilege('desk_app', 'desk.fadm_session_revoke(bytea)', 'execute') and not has_function_privilege('public', 'desk.fadm_session_create(uuid,bytea,integer)', 'execute') and not has_function_privilege('public', 'desk.fadm_session_revoke(bytea)', 'execute');
